    C --> D[DROP TABLE users; Executed];
    D --> E[-- Comments Out Remaining Query];
    E --> F[Database Compromised];
    B -- No, Input Sanitized --> G[Input Treated as Literal String];
    G --> H[Safe Database Operation];
```

